const { useState } = React;

function App() {
  const [page, setPage] = useState("register");
  const [fullName, setFullName] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [agreeTerms, setAgreeTerms] = useState(false);
  const [error, setError] = useState("");

  function handleRegister(e) {
    e.preventDefault();
    if (!fullName.trim()) {
      setError("Full name is required.");
      return;
    }
    if (!email.trim()) {
      setError("Email is required.");
      return;
    }
    if (!password) {
      setError("Password is required.");
      return;
    }
    if (!confirmPassword) {
      setError("Confirm password is required.");
      return;
    }
    if (password !== confirmPassword) {
      setError("Passwords do not match.");
      return;
    }
    if (!agreeTerms) {
      setError("You must agree to the terms.");
      return;
    }
    setError("");
    alert("Registered successfully!");
  }

  if (page === "login") {
    return (
      <main style={styles.container}>
        <h1 style={styles.title}>Login Page</h1>
        <p style={{ marginTop: 20 }}>
          Don't have an account?{' '}
          <a href="#" onClick={e => { e.preventDefault(); setPage("register"); }} style={styles.link}>
            Create Account
          </a>
        </p>
      </main>
    );
  }

  return (
    <main style={styles.container}>
      <h1 style={styles.title}>Create Account</h1>
      <form onSubmit={handleRegister} noValidate style={styles.form}>
        <label style={styles.label} htmlFor="fullName">Full name</label>
        <input
          id="fullName"
          type="text"
          value={fullName}
          onChange={e => setFullName(e.target.value)}
          style={styles.input}
          placeholder="Full name"
          aria-describedby="fullNameError"
        />

        <label style={styles.label} htmlFor="email">Email</label>
        <input
          id="email"
          type="email"
          value={email}
          onChange={e => setEmail(e.target.value)}
          style={styles.input}
          placeholder="Email"
          aria-describedby="emailError"
        />

        <label style={styles.label} htmlFor="password">Password</label>
        <input
          id="password"
          type="password"
          value={password}
          onChange={e => setPassword(e.target.value)}
          style={styles.input}
          placeholder="Password"
          aria-describedby="passwordError"
        />

        <label style={styles.label} htmlFor="confirmPassword">Confirm password</label>
        <input
          id="confirmPassword"
          type="password"
          value={confirmPassword}
          onChange={e => setConfirmPassword(e.target.value)}
          style={styles.input}
          placeholder="Confirm password"
          aria-describedby="confirmPasswordError"
        />

        <label style={{ ...styles.checkboxLabel, marginTop: 12 }}>
          <input
            type="checkbox"
            checked={agreeTerms}
            onChange={e => setAgreeTerms(e.target.checked)}
            style={styles.checkbox}
          />
          I agree to the terms
        </label>

        {error && (
          <p role="alert" style={styles.error}>
            {error}
          </p>
        )}

        <button type="submit" style={styles.button}>
          Create account
        </button>
      </form>

      <p style={styles.loginText}>
        Already have an account?{' '}
        <a
          href="#"
          onClick={e => {
            e.preventDefault();
            setPage("login");
          }}
          style={styles.link}
        >
          Login
        </a>
      </p>

      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Indie+Flower&display=swap');
      `}</style>
    </main>
  );
}

const styles = {
  container: {
    fontFamily: `'Indie Flower', cursive, sans-serif`,
    maxWidth: 360,
    margin: '40px auto',
    padding: 20,
    border: '1.5px solid black',
    borderRadius: 8,
    backgroundColor: '#fff',
    boxShadow: '2px 2px 6px rgba(0,0,0,0.1)',
    userSelect: 'none',
  },
  title: {
    fontWeight: 'normal',
    fontSize: 28,
    textAlign: 'center',
    marginBottom: 24,
  },
  form: {
    display: 'flex',
    flexDirection: 'column',
  },
  label: {
    fontSize: 14,
    marginBottom: 4,
    userSelect: 'none',
  },
  input: {
    fontFamily: `'Indie Flower', cursive, sans-serif`,
    fontSize: 18,
    padding: '8px 12px',
    marginBottom: 16,
    border: '1.5px solid black',
    borderRadius: 4,
    outlineOffset: 2,
    outlineColor: 'transparent',
    transition: 'outline-color 0.2s ease',
  },
  checkboxLabel: {
    fontSize: 16,
    display: 'flex',
    alignItems: 'center',
    gap: 8,
    userSelect: 'none',
  },
  checkbox: {
    width: 18,
    height: 18,
    border: '1.5px solid black',
    borderRadius: 3,
    cursor: 'pointer',
  },
  button: {
    fontFamily: `'Indie Flower', cursive, sans-serif`,
    fontSize: 20,
    padding: '10px 0',
    borderRadius: 12,
    border: '1.5px solid black',
    backgroundColor: 'transparent',
    cursor: 'pointer',
    userSelect: 'none',
    marginTop: 8,
  },
  loginText: {
    marginTop: 20,
    fontSize: 16,
    textAlign: 'center',
    userSelect: 'none',
  },
  link: {
    textDecoration: 'underline',
    cursor: 'pointer',
    color: 'black',
  },
  error: {
    color: 'red',
    fontSize: 14,
    marginBottom: 8,
    userSelect: 'none',
  },
};

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

